    [2021, t('«Shenchjou-13»; 7-noyabrda ochiq kosmosga chiqdi','«Шэньчжоу-13»; 7 ноября вышла в открытый космос','Shenzhou 13; spacewalk on 7 November')],
    [2022, t('16-aprelda 183 kunlik ekspeditsiyadan qaytdi','16 апреля вернулась из 183-суточной экспедиции','Returned on 16 April from a 183-day expedition')]
