    [t('«Mir» stansiyasi','Станция «Мир»','Mir space station'), t('1986–2001-yillarda ishlagan sovet/rossiya ko‘p modulli orbital stansiyasi.','Советская/российская многомодульная орбитальная станция, работавшая в 1986–2001 годах.','The Soviet/Russian multi-module orbital station that operated from 1986 to 2001.'), null],
    [t('Xalqaro kosmik stansiya','Международная космическая станция','International Space Station'), t('Sharipov 2004–2005-yillarda 10-ekspeditsiya tarkibida ishlagan xalqaro orbital laboratoriya.','Международная орбитальная лаборатория, на которой Шарипов работал в 2004–2005 годах в составе 10-й экспедиции.','The international orbital laboratory where Sharipov worked on Expedition 10 in 2004–2005.'), null],
    [t('«Soyuz TMA» kemasi','Корабль «Союз ТМА»','Soyuz TMA spacecraft'), t('Uch o‘rinli rus kemasi; Sharipov «Soyuz TMA-5»ning komandiri sifatida uni XKSga olib borib, qaytargan.','Трёхместный российский корабль; Шарипов как командир «Союза ТМА-5» привёл его к МКС и вернул на Землю.','A three-seat Russian spacecraft; as commander of Soyuz TMA-5, Sharipov flew it to the ISS and back.'), null]
