    [2009, t('Soyuz TMA-14 / XKS-19/20','Союз ТМА-14 / МКС-19/20','Soyuz TMA-14 / ISS Expeditions 19/20'), t('26-mart – 11-oktabr, M. Barratt bilan; 19- va 20-ekspeditsiyalar komandiri. Birinchi olti kishilik ekipaj; 198 kun 16 soat.','26 марта – 11 октября, с М. Барраттом; командир 19-й и 20-й экспедиций. Первый экипаж из шести человек; 198 сут 16 ч.','26 March – 11 October, with M. Barratt; commander of Expeditions 19 and 20. First six-person crew; 198 d 16 h.')],
    [2012, t('Soyuz TMA-04M / XKS-31/32','Союз ТМА-04М / МКС-31/32','Soyuz TMA-04M / ISS Expeditions 31/32'), t('15-may – 17-sentabr, S. Revin va J. Akaba bilan; 32-ekspeditsiya komandiri. Yu. Malenchenko bilan ochiq kosmosga chiqish; taxminan 124 kun.','15 мая – 17 сентября, с С. Ревиным и Дж. Акабой; командир 32-й экспедиции. Выход в открытый космос с Ю. Маленченко; около 124 суток.','15 May – 17 September, with S. Revin and J. Acaba; Expedition 32 commander. Spacewalk with Yu. Malenchenko; about 124 days.')],
    [2015, t('Soyuz TMA-16M / XKS-43/44','Союз ТМА-16М / МКС-43/44','Soyuz TMA-16M / ISS Expeditions 43/44'), t('27-mart – 12-sentabr, M. Korniyenko va S. Kelli bilan; 44-ekspeditsiya komandiri. Kosmosdagi jami vaqt bo‘yicha jahon rekordi; 168 kun.','27 марта – 12 сентября, с М. Корниенко и С. Келли; командир 44-й экспедиции. Мировой рекорд суммарного времени в космосе; 168 суток.','27 March – 12 September, with M. Kornienko and S. Kelly; Expedition 44 commander. World record for total time in space; 168 days.')]
